 private void AllocateDefaultShadowTexture()
 {
 defaultShadowTexture = RTHandles.Alloc(
 1, 1,
 depthBufferBits: DepthBits.Depth16,
 isShadowMap: true,
 name: "Default Shadow Texture"
 );
 }

 private static void ReAllocateColorRTHandle(ref RTHandle handle, int width, int height,
 GraphicsFormat colorFormat, string name)
 {
 if (handle != null && handle.rt != null &&
 handle.rt.width == width && handle.rt.height == height &&
 handle.rt.graphicsFormat == colorFormat)
 return;

 handle?.Release();
 handle = RTHandles.Alloc(
 width, height,
 colorFormat: colorFormat,
 name: name
 );
 }

 private static void ReAllocateDepthRTHandle(ref RTHandle handle, int width, int height, string name)
 {
 if (handle != null && handle.rt != null &&
