{"rawEvent":{"message_id":"019d7c4d435171b396e1d633eed9d198","conversation_id":"019d6e17fc1f7daabf5314974e3bb0d5","tool_call_id":"tooluse_5MA2Wxzkm1y0LHXWxu6uHy","document":{"file_path":"/Users/archerdu/UnityProject/ArcToonRP/Packages/com.arctoon.render-pipeline/Runtime/Data/TransparencyResources.cs","sub_content":"TransparencyResources.cs","sub_content_event":"open_editor","sub_content_event_value":"/Users/archerdu/UnityProject/ArcToonRP/Packages/com.arctoon.render-pipeline/Runtime/Data/TransparencyResources.cs","sub_content_tip":"/Users/archerdu/UnityProject/ArcToonRP/Packages/com.arctoon.render-pipeline/Runtime/Data/TransparencyResources.cs","apply_content":"using System;
using UnityEngine;
using UnityEngine.Experimental.Rendering;
using UnityEngine.Rendering;

namespace ArcToon.Runtime.Data
{
 /// <summary>
 /// Transparency rendering RTHandles: weighted average and depth peeling buffers.
 /// Used by: TransparentPass (exclusively).
 /// </summary>
 public class TransparencyResources : IDisposable
 {
 // Weighted Average
 public RTHandle waAccumulateRGBA;
 public RTHandle waRevealage;
 public RTHandle waBackgroundColor;

 // Depth Peeling
 public const int DepthPeelingLayers = 4;
 public RTHandle dpOpaqueColorBuffer;
 public RTHandle dpCompositeArray;
 public RTHandle[] dpDualDepthBuffer = new RTHandle[2];

 /// <summary>
 /// Allocate or re-allocate transparency rendering RTHandles if the size has changed.
 /// Called each frame alongside camera resource allocation.
 /// </summary>
 public void Allocate(int width, int height, bool useHDR)
 {
 var colorFormat = SystemInfo.GetGraphicsFormat(useHDR ? DefaultFormat.HDR : DefaultFormat.LDR);

 // Weighted Average
 RenderTextureDescriptor waAccumDesc = new(width, height, colorFormat, 0);
 RenderTextureDescriptor waRevealDesc = new(width, height, GraphicsFormat.R16_UNorm, 0);
 RenderTextureDescriptor waBgDesc = new(width, height, colorFormat, 0);

 RTHandleUtility.ReAllocateIfNeeded(ref waAccumulateRGBA, waAccumDesc, name: "Weighted Average Accumulate RGBA");
 RTHandleUtility.ReAllocateIfNeeded(ref waRevealage, waRevealDesc, name: "Weighted Average Revealage");
 RTHandleUtility.ReAllocateIfNeeded(ref waBackgroundColor, waBgDesc, name: "Weighted Average Background Color");

 // Depth Peeling
 RenderTextureDescriptor dpCompositeDesc = new(width, height, colorFormat, 0)
 {
 dimension = TextureDimension.Tex2DArray,
 volumeDepth = 6,
 };
 // Match depthAttachment format (D32_SFloat_S8_UInt) as old RenderGraph code
 // used depthAttachment.GetDescriptor() to create these buffers.
 RenderTextureDescriptor dpDepthDesc = new(width, height, GraphicsFormat.None, GraphicsFormat.D32_SFloat_S8_UInt);
 RenderTextureDescriptor dpColorDesc = new(width, height, colorFormat, 0);

 RTHandleUtility.ReAllocateIfNeeded(ref dpCompositeArray, dpCompositeDesc, name: "Depth Peeling Composite Array");
 RTHandleUtility.ReAllocateIfNeeded(ref dpDualDepthBuffer[0], dpDepthDesc, name: "Depth Peeling Dual Depth Buffer 0");
 RTHandleUtility.ReAllocateIfNeeded(ref dpDualDepthBuffer[1], dpDepthDesc, name: "Depth Peeling Dual Depth Buffer 1");
 RTHandleUtility.ReAllocateIfNeeded(ref dpOpaqueColorBuffer, dpColorDesc, name: "Depth Peeling Opaque Color Buffer");
 }

 public void Dispose()
 {
 waAccumulateRGBA?.Release();
 waRevealage?.Release();
 waBackgroundColor?.Release();
 dpOpaqueColorBuffer?.Release();
 dpCompositeArray?.Release();
 dpDualDepthBuffer[0]?.Release();
 dpDualDepthBuffer[1]?.Release();
 }
 }
}
