        // Allocate LUT ...
    }

    public override void Render(CommandBuffer cmd, RTHandle source, RTHandle destination)
    {
        // 1. Configure uniforms (color adjustments, white balance, etc.)
        // 2. Bake LUT: source → colorLUT
        // 3. Apply LUT: source → destination
    }

    public override void Dispose() => colorLUT?.Release();
}
