{"rawEvent":{"message_id":"019d808e8db470a4acca68e8b8a9f9aa","conversation_id":"019d6e17fc1f7daabf5314974e3bb0d5","tool_call_id":"tooluse_nWFsfYMZDzYyqIG4Bnlc0V","document":{"file_path":"/Users/archerdu/UnityProject/ArcToonRP/Packages/com.arctoon.render-pipeline/Runtime/Passes/PostProcessing/Processors/BloomSettings.cs","sub_content":"BloomSettings.cs","sub_content_event":"open_editor","sub_content_event_value":"/Users/archerdu/UnityProject/ArcToonRP/Packages/com.arctoon.render-pipeline/Runtime/Passes/PostProcessing/Processors/BloomSettings.cs","sub_content_tip":"/Users/archerdu/UnityProject/ArcToonRP/Packages/com.arctoon.render-pipeline/Runtime/Passes/PostProcessing/Processors/BloomSettings.cs","apply_content":"using System;
using UnityEngine;

namespace ArcToon.Passes.PostProcessing
{
 /// <summary>
 /// Settings for the Bloom post-processing effect.
 /// Mirrors the parameters from the old PostFXConfig.BloomSettings.
 /// </summary>
 [Serializable]
 public class BloomSettings : PostProcessSettings
 {
 public override int Order => 100;

 public enum Mode
 {
 Additive,
 Scattering
 }

 public Mode mode = Mode.Scattering;

 public bool ignoreRenderScale = true;

 [Range(0.05f, 0.95f)] public float scatter = 0.5f;

 [Range(0f, 16f)] public int maxIterations = 2;

 [Min(1f)] public int downscaleLimit = 10;

 [Min(0f)] public float threshold = 1f;

 [Range(0f, 1f)] public float thresholdKnee = 1f;

 [Min(0f)] public float intensity = 1f;

 public bool fadeFireflies = true;

 public bool bicubicUpsampling = true;
 }
}
