using ArcToon.Utils;
using ArcToon.Utils.Extensions;
using UnityEngine;
using UnityEngine.Rendering;

namespace ArcToon.Passes.PostProcessing
{
    /// <summary>
    /// Static utility for full-screen post-processing draw calls.
    /// Replaces the old instance-based PostFXStack class.
    /// </summary>
    public static class PostFXUtility
    {
        private static readonly int sourceTextureID = Shader.PropertyToID("_PostFXSource");

        /// <summary>
        /// Full-screen draw with explicit material and pass index.
        /// Sets the source texture as a global shader property, then draws a full-screen triangle.
        /// </summary>
        public static void Draw(CommandBuffer cmd,
            RenderTargetIdentifier src, RenderTargetIdentifier dst,
            Material material, int pass)
        {
            cmd.SetGlobalTexture(sourceTextureID, src);
            cmd.SetRenderTarget(dst,
                RenderBufferLoadAction.DontCare, RenderBufferStoreAction.Store);
            cmd.DrawScreenFilledTriangle(material, pass);
        }

        /// <summary>
        /// Simple blit (copy) from source to destination using the built-in blitter shader.
        /// </summary>
        public static void Blit(CommandBuffer cmd,
            RenderTargetIdentifier src, RenderTargetIdentifier dst)
        {
            var blitMaterial = ShaderResourceManager.AcquireTransientMaterial(InternalShader.Path.PostFXStack);
            // Pass.Copy = 25 in the old PostFXStack enum
            // We use the Copy pass from the existing Post FX Stack shader
            Draw(cmd, src, dst, blitMaterial, (int)PostFXStack.Pass.Copy);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEngine;

namespace ArcToon.Passes.PostProcessing
{
    /// <summary>
    /// Composable post-processing configuration.
    /// Holds a polymorphic list of PostProcessSettings that can be freely added/removed in Inspector.
    /// Each PostProcessor retrieves its own settings via GetSettings&lt;T&gt;().
    /// </summary>
    [CreateAssetMenu(menuName = "Rendering/ArcToon Post Process Config")]
    public class PostProcessConfig : ScriptableObject
    {
        [SerializeReference]
        public List<PostProcessSettings> settings = new();

        /// <summary>
        /// Get settings of a specific type. Returns null if not found.
        /// </summary>
        public T GetSettings<T>() where T : PostProcessSettings
        {
            return settings.OfType<T>().FirstOrDefault();
        }

        /// <summary>
        /// Check if this config contains settings of a specific type.
        /// </summary>
        public bool HasSettings<T>() where T : PostProcessSettings
        {
            return settings.OfType<T>().Any();
        }

        /// <summary>
        /// Check if post-processing should be applied to the given camera.
        /// </summary>
        public static bool AreApplicableTo(Camera camera)
        {
#if UNITY_EDITOR
            if (camera.cameraType == CameraType.SceneView &&
                !SceneView.currentDrawingSceneView.sceneViewState.showImageEffects)
            {
                return false;
            }
#endif
            return camera.cameraType <= CameraType.SceneView;
        }
    }
}

using System;

namespace ArcToon.Passes.PostProcessing
{
    /// <summary>
    /// Abstract base class for all post-processing effect settings.
    /// Each concrete subclass holds the parameters for a single effect.
    /// Serialized polymorphically via [SerializeReference] in PostProcessConfig.
    /// </summary>
    [Serializable]
    public abstract class PostProcessSettings
    {
        /// <summary>
        /// Execution order within the post-processing chain.
        /// Lower values execute first.
        /// </summary>
        public abstract int Order { get; }

        /// <summary>
        /// Whether this effect is enabled.
        /// </summary>
        public bool enabled = true;
    }
}

