 public void UpdateCasterInfo()
 {
 UpdateRendererList();
 UpdateRendererMaterialProperties();
 UpdateShadowCasterRendererList();
 }

 private void UpdateRendererList()
 {
 renderers.Clear();
 GetComponentsInChildren(true, renderers);
