StructuredBuffer<PointLightBufferData> _PointLightData;

static const float3 pointShadowPlanes[6] =
{
 float3(-1.0, 0.0, 0.0),
 float3(1.0, 0.0, 0.0),
 float3(0.0, -1.0, 0.0),
 float3(0.0, 1.0, 0.0),
 float3(0.0, 0.0, -1.0),
 float3(0.0, 0.0, 1.0)
