 if (shadowMapDepth > positionSTS.z)
 #else
 if (shadowMapDepth < positionSTS.z)
 #endif
 {
 blockerDepthSum += shadowMapDepth;
 blockerCount += 1.0;
 }
 }
 return float2(blockerDepthSum / max(blockerCount, 0.001), blockerCount);
}

